-- Prepared for a separate, private test project. Not applied to a hosted project.
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA extensions;
CREATE SCHEMA prisma_agenda;
REVOKE ALL ON SCHEMA prisma_agenda FROM PUBLIC;
SET search_path TO prisma_agenda,extensions,pg_catalog;
DO $$ BEGIN
  IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='prisma_agenda_runtime') THEN
    CREATE ROLE prisma_agenda_runtime NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS;
  ELSIF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='prisma_agenda_runtime' AND (rolsuper OR rolbypassrls OR rolcanlogin OR rolcreatedb OR rolcreaterole)) THEN
    RAISE EXCEPTION 'Existing runtime role has unexpected privileges';
  END IF;
  EXECUTE format('GRANT prisma_agenda_runtime TO %I',current_user);
END $$;

CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);

INSERT INTO schema_version VALUES(1) ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS organizations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS units(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,settings TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);

CREATE TABLE IF NOT EXISTS config_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,version INTEGER NOT NULL,settings TEXT NOT NULL,created TIMESTAMPTZ NOT NULL,UNIQUE(unit,version));

CREATE TABLE IF NOT EXISTS rooms(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL REFERENCES units(id),name TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS people(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL REFERENCES units(id),name TEXT NOT NULL,kind TEXT NOT NULL,profession TEXT,registry TEXT,cpf TEXT,phone TEXT,registration TEXT,plan_until TEXT,tutor INTEGER REFERENCES people(id),active INTEGER NOT NULL DEFAULT 1,UNIQUE(unit,registry),UNIQUE(unit,cpf));

CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,person INTEGER REFERENCES people(id),login TEXT NOT NULL,role TEXT NOT NULL,password TEXT,generation INTEGER NOT NULL DEFAULT 0,UNIQUE(org,login));

CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,"user" INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires TIMESTAMPTZ NOT NULL,temporary INTEGER NOT NULL,generation INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS reservations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,room INTEGER NOT NULL REFERENCES rooms(id),person INTEGER NOT NULL REFERENCES people(id),student INTEGER REFERENCES people(id),tutor INTEGER REFERENCES people(id),category TEXT NOT NULL,start TIMESTAMPTZ NOT NULL,"end" TIMESTAMPTZ NOT NULL,status TEXT NOT NULL,payment TEXT NOT NULL,presence TEXT NOT NULL DEFAULT 'pendente',whatsapp INTEGER NOT NULL DEFAULT 0,training INTEGER NOT NULL DEFAULT 0,used INTEGER NOT NULL DEFAULT 0,snapshot TEXT NOT NULL,expires TIMESTAMPTZ,created TIMESTAMPTZ NOT NULL,operator INTEGER NOT NULL,relocated INTEGER NOT NULL DEFAULT 0);

CREATE INDEX IF NOT EXISTS reservation_interval ON reservations(unit,start,"end");

CREATE TABLE IF NOT EXISTS benefits(org INTEGER NOT NULL,unit INTEGER NOT NULL,cpf TEXT NOT NULL,month TEXT NOT NULL,reservation INTEGER NOT NULL REFERENCES reservations(id),PRIMARY KEY(org,unit,cpf,month));

CREATE TABLE IF NOT EXISTS payments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,reservation INTEGER NOT NULL UNIQUE REFERENCES reservations(id),amount INTEGER NOT NULL,reference TEXT NOT NULL,created TIMESTAMPTZ NOT NULL,operator INTEGER NOT NULL,UNIQUE(org,unit,reference));

CREATE TABLE IF NOT EXISTS refunds(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,reservation INTEGER NOT NULL UNIQUE REFERENCES reservations(id),amount INTEGER NOT NULL,retained INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pendente',reference TEXT,created TIMESTAMPTZ NOT NULL,operator INTEGER);

CREATE TABLE IF NOT EXISTS penalties(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,identity TEXT NOT NULL,reservation INTEGER NOT NULL UNIQUE,start TIMESTAMPTZ NOT NULL,"end" TIMESTAMPTZ NOT NULL,reason TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS blocks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,room INTEGER,person INTEGER,start TIMESTAMPTZ NOT NULL,"end" TIMESTAMPTZ NOT NULL,reason TEXT NOT NULL,operator INTEGER NOT NULL,origin TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS work(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,person INTEGER NOT NULL REFERENCES people(id),weekday INTEGER NOT NULL,start TEXT NOT NULL,"end" TEXT NOT NULL,valid_from TEXT NOT NULL,valid_to TEXT NOT NULL,contract_minutes INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS schedules(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL,month TEXT NOT NULL,anchor TEXT NOT NULL,assignments TEXT NOT NULL,errors TEXT NOT NULL,created TIMESTAMPTZ NOT NULL);

CREATE TABLE IF NOT EXISTS swaps(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,schedule INTEGER NOT NULL,version INTEGER NOT NULL,source INTEGER NOT NULL,target INTEGER NOT NULL,assignment INTEGER NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS reasons(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,title TEXT NOT NULL,requires_detail INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1);

CREATE TABLE IF NOT EXISTS audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,actor INTEGER,action TEXT NOT NULL,entity TEXT NOT NULL,data TEXT NOT NULL,created TIMESTAMPTZ NOT NULL);

CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,org INTEGER NOT NULL,unit INTEGER NOT NULL,message TEXT NOT NULL,created TIMESTAMPTZ NOT NULL);

-- Tenant-scoped foreign keys protect associations even outside the HTTP service.
ALTER TABLE units ADD CONSTRAINT units_org_id UNIQUE(org,id);
ALTER TABLE rooms ADD CONSTRAINT rooms_org_unit_id UNIQUE(org,unit,id);
ALTER TABLE people ADD CONSTRAINT people_org_unit_id UNIQUE(org,unit,id);
ALTER TABLE users ADD CONSTRAINT users_org_unit_id UNIQUE(org,unit,id);
ALTER TABLE reservations ADD CONSTRAINT reservations_org_unit_id UNIQUE(org,unit,id);
ALTER TABLE reservations ADD CONSTRAINT reservation_duration CHECK(start < "end");
ALTER TABLE reservations ADD CONSTRAINT reservation_room_tenant FOREIGN KEY(org,unit,room) REFERENCES rooms(org,unit,id);
ALTER TABLE reservations ADD CONSTRAINT reservation_person_tenant FOREIGN KEY(org,unit,person) REFERENCES people(org,unit,id);
ALTER TABLE reservations ADD CONSTRAINT reservation_student_tenant FOREIGN KEY(org,unit,student) REFERENCES people(org,unit,id);
ALTER TABLE reservations ADD CONSTRAINT reservation_tutor_tenant FOREIGN KEY(org,unit,tutor) REFERENCES people(org,unit,id);
ALTER TABLE people ADD CONSTRAINT tutor_tenant FOREIGN KEY(org,unit,tutor) REFERENCES people(org,unit,id);
ALTER TABLE reservations ADD CONSTRAINT no_room_overlap EXCLUDE USING gist
(org WITH =, unit WITH =, room WITH =, tstzrange(start,"end",'[)') WITH &&)
WHERE (status IN ('confirmed','awaiting_payment','no_show'));
CREATE TABLE reservation_actors (
 org INTEGER NOT NULL, unit INTEGER NOT NULL,
 reservation INTEGER NOT NULL, person INTEGER NOT NULL,
 start TIMESTAMPTZ NOT NULL, "end" TIMESTAMPTZ NOT NULL,
 PRIMARY KEY(org,unit,reservation,person),
 FOREIGN KEY(org,unit,reservation) REFERENCES reservations(org,unit,id) ON DELETE CASCADE,
 FOREIGN KEY(org,unit,person) REFERENCES people(org,unit,id),
 EXCLUDE USING gist (org WITH =,unit WITH =,person WITH =,tstzrange(start,"end",'[)') WITH &&)
);
CREATE FUNCTION sync_reservation_actors() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=prisma_agenda,pg_catalog AS $$
BEGIN
 DELETE FROM reservation_actors WHERE reservation=NEW.id AND org=NEW.org AND unit=NEW.unit;
 IF NEW.status IN ('confirmed','awaiting_payment','no_show') THEN
  INSERT INTO reservation_actors(org,unit,reservation,person,start,"end")
  SELECT NEW.org,NEW.unit,NEW.id,p.id,NEW.start,NEW."end"
  FROM (SELECT NEW.person AS id UNION SELECT NEW.tutor AS id) p WHERE p.id IS NOT NULL;
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION sync_reservation_actors() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION sync_reservation_actors() TO prisma_agenda_runtime;
CREATE TRIGGER reservation_actors_changed AFTER INSERT OR UPDATE ON reservations
FOR EACH ROW EXECUTE FUNCTION sync_reservation_actors();
