ALTER TABLE refunds ADD CONSTRAINT refunds_reservation_tenant FOREIGN KEY(org,unit,reservation) REFERENCES reservations(org,unit,id);
ALTER TABLE penalties ADD CONSTRAINT penalties_reservation_tenant FOREIGN KEY(org,unit,reservation) REFERENCES reservations(org,unit,id);
