-- The Data API receives no grant to this private schema. RLS is additional isolation.
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_context ON organizations FOR ALL TO prisma_agenda_runtime USING ((COALESCE(current_setting('prisma.worker',true),'0')='1') OR (id::text=current_setting('prisma.org',true))) WITH CHECK ((COALESCE(current_setting('prisma.worker',true),'0')='1') OR (id::text=current_setting('prisma.org',true)));
ALTER TABLE units ENABLE ROW LEVEL SECURITY;
CREATE POLICY backend_context ON units FOR ALL TO prisma_agenda_runtime USING ((COALESCE(current_setting('prisma.worker',true),'0')='1') OR (org::text=current_setting('prisma.org',true) AND (current_setting('prisma.role',true)='admin' OR id::text=current_setting('prisma.unit',true)))) WITH CHECK ((COALESCE(current_setting('prisma.worker',true),'0')='1') OR (org::text=current_setting('prisma.org',true) AND (current_setting('prisma.role',true)='admin' OR id::text=current_setting('prisma.unit',true))));
